#!/usr/bin/env node
// Generates packages/ui/src/tokens.css from shared/design/tokens.json (the single source of the design
// tokens). With --check it only verifies that the generated file is up to date (exit code 1 if not).
// The generated file is protected by .claude/hooks/generated-guard.mjs: agents edit the JSON, never the CSS.
// Usage: node scripts/build-tokens.mjs [--check]
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const source = join(root, "shared/design/tokens.json");
const target = join(root, "packages/ui/src/tokens.css");

// { color: { primary: "#..." }, space: { sm: "4px" } } -> --color-primary: #...;
function flatten(obj, prefix = []) {
  return Object.entries(obj).flatMap(([k, v]) => (v && typeof v === "object" ? flatten(v, [...prefix, k]) : [[[...prefix, k].join("-"), String(v)]]));
}

export function render(tokens) {
  const lines = flatten(tokens).map(([name, value]) => `  --${name}: ${value};`);
  return `/* Generated by scripts/build-tokens.mjs from shared/design/tokens.json. Do not edit by hand. */\n:root {\n${lines.join("\n")}\n}\n`;
}

const css = render(JSON.parse(readFileSync(source, "utf8")));
if (process.argv.includes("--check")) {
  const current = existsSync(target) ? readFileSync(target, "utf8") : "";
  if (current !== css) {
    console.error("packages/ui/src/tokens.css is stale: run `npm run tokens`.");
    process.exit(1);
  }
  console.log("Design tokens up to date.");
} else {
  writeFileSync(target, css);
  console.log("packages/ui/src/tokens.css generated.");
}
